<?php $tituloPaginaAdmin='Gestão de pedidos';require __DIR__.'/../includes/cabecalho-admin.php';$db=criarConexaoBancoDados();if($_SERVER['REQUEST_METHOD']==='POST'){$db->prepare('UPDATE pedidos SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);redirecionar('pedidos.php');}$ps=$db->query('SELECT p.*,u.nome FROM pedidos p JOIN usuarios u ON u.id=p.usuario_id ORDER BY p.data_pedido DESC')->fetchAll();?><h1>Pedidos</h1><table><tr><th>#</th><th>Cliente</th><th>Entrega/frete</th><th>Total</th><th>Status</th></tr><?php foreach($ps as $p):?><tr><td><?=$p['id']?></td><td><?=escapar($p['nome'])?></td><td><?=escapar($p['modalidade_entrega'])?> · <?=valorMoeda((float)$p['frete'])?></td><td><?=valorMoeda((float)$p['valor_total'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$p['id']?>"><select name="status"><?php foreach(statusPedido() as $k=>$v):?><option value="<?=$k?>" <?=$k===$p['status']?'selected':''?>><?=$v?></option><?php endforeach;?></select><button>Atualizar</button></form></td></tr><?php endforeach;?></table><?php require __DIR__.'/../includes/rodape-admin.php';?>